def can_weave(a: str, b: str, c: str) -> bool:
    if len(a) + len(b) != len(c):
        return False                     # every character is used exactly once
    ok = [False] * (len(b) + 1)          # ok[j]: c[:i + j] can be woven from a[:i] and b[:j]
    for i in range(len(a) + 1):
        for j in range(len(b) + 1):
            if i == 0 and j == 0:
                ok[j] = True             # nothing woven from nothing
            else:                        # the last character of c[:i + j] came from a or from b
                from_a = i > 0 and ok[j] and a[i - 1] == c[i + j - 1]       # ok[j] is still row i - 1
                from_b = j > 0 and ok[j - 1] and b[j - 1] == c[i + j - 1]
                ok[j] = from_a or from_b
    return ok[-1]

