perf.naive:
def can_weave(a: str, b: str, c: str) -> bool:
    if len(a) + len(b) != len(c):
        return False
    def weave(i, j):                     # can a[i:] and b[j:] weave c[i + j:]? re-asked on every path
        if i == len(a) and j == len(b):
            return True
        k = i + j
        if i < len(a) and a[i] == c[k] and weave(i + 1, j):
            return True
        return j < len(b) and b[j] == c[k] and weave(i, j + 1)
    return weave(0, 0)
